(6512446, 967973, 123833, '<td valign="top">Looks like nightpixels'' PP</td>', 'Looks like nightpixels'' PP', '2011-08-22 19:24:35.000000', NULL, 1),
(6512447, 967624, 40484, '<td valign="top">Thank you for educating me. I did not know that chickaree was a description for a squirrel. Nice clarity and definition on the shot with good dof to blur the background but keep the foreground crisp.</td>', 'Thank you for educating me. I did not know that chickaree was a description for a squirrel. Nice clarity and definition on the shot with good dof to blur the background but keep the foreground crisp.', '2011-08-22 19:24:49.000000', NULL, 1),
(6512465, 968492, 74559, '<td valign="top">What a beauty! Excellent job at capturing such detail and tones on a dark kitty, not an easy task.</td>', 'What a beauty! Excellent job at capturing such detail and tones on a dark kitty, not an easy task.', '2011-08-22 19:44:46.000000', NULL, 1),
(6512466, 968001, 74559, '<td valign="top">Love the soft colors of the ocean and sky, and you''ve made her skin look like silk, just lovely. Would have been nice to clone out the sensor dust, but no biggie, this is a beautiful image.</td>', 'Love the soft colors of the ocean and sky, and you''ve made her skin look like silk, just lovely. Would have been nice to clone out the sensor dust, but no biggie, this is a beautiful image.', '2011-08-22 19:47:19.000000', NULL, 1),
