INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6519358, 968640, 117474, '<td valign="top">I think the black and white conversion of this made it for me. And the curves of the leaf. And the vertical orientation. <br/> <br/>Somehow it says I gave you 5 for this. Which is bizarre! Must have pressed 5 on the keypad instead of 8. Hmm. That''s the second time I have noticed this happening. I wonder how often it happens.</td>', 'I think the black and white conversion of this made it for me. And the curves of the leaf. And the vertical orientation.  Somehow it says I gave you 5 for this. Which is bizarre! Must have pressed 5 on the keypad instead of 8. Hmm. That''s the second time I have noticed this happening. I wonder how often it happens.', '2011-08-29 09:15:08.000000', NULL, 0),
(6519361, 968620, 100831, '<td valign="top">Clearly Cory''s Collection - ha!! Hi neighbor!</td>', 'Clearly Cory''s Collection - ha!! Hi neighbor!', '2011-08-29 09:15:47.000000', NULL, 0),
(6519365, 968155, 100831, '<td valign="top">My power was knocked off....... never got to comment this challenge but this was cleary a favorited - what a wonderful perspective and overall feel!!</td>', 'My power was knocked off....... never got to comment this challenge but this was cleary a favorited - what a wonderful perspective and overall feel!!', '2011-08-29 09:18:17.000000', NULL, 0),
(6519370, 968049, 37265, '<td valign="top">Thank you all for your comments. Landz, in this region this would be considered a cliche Chesapeake photo and even without a caption it would say "Chesapeake." But in areas where people are not familiar with the Chesapeake Bay I see your point. Robert, this is a place we visit often and next time we''re there I''ll try your suggestion of lowering the perspective to raise the pilings into the skyline.</td>', 'Thank you all for your comments. Landz, in this region this would be considered a cliche Chesapeake photo and even without a caption it would say "Chesapeake." But in areas where people are not familiar with the Chesapeake Bay I see your point. Robert, this is a place we visit often and next time we''re there I''ll try your suggestion of lowering the perspective to raise the pilings into the skyline.', '2011-08-29 09:23:14.000000', NULL, 0),
(6519374, 968625, 15711, '<td valign="top">Shannon!!  Long time no see, man.  Great to have you in the top spot!!</td>', 'Shannon!!  Long time no see, man.  Great to have you in the top spot!!', '2011-08-29 09:30:55.000000', NULL, 0),
(6519377, 968571, 15711, '<td valign="top">Seriously??  This was the blue in my book. ;)</td>', 'Seriously??  This was the blue in my book. ;)', '2011-08-29 09:32:51.000000', NULL, 0),
(6519393, 968523, 98339, '<td valign="top">seriously a beautiful picture...so very well done....congrats on top 10!!</td>', 'seriously a beautiful picture...so very well done....congrats on top 10!!', '2011-08-29 09:41:08.000000', NULL, 0),
(6519401, 968620, 117474, '<td valign="top">Hmm. I gave this an 8. Nearly 2 more than it deserved, apparently. Must vote lower next time. <br/> <br/>:-) Just kidding. Nice image. Loved the background.</td>', 'Hmm. I gave this an 8. Nearly 2 more than it deserved, apparently. Must vote lower next time.  :-) Just kidding. Nice image. Loved the background.', '2011-08-29 09:44:37.000000', NULL, 0),
(6519410, 967901, 59029, '<td valign="top">FWIW, this image strikes me more as digital art than a photograph.  There are lots of cool elements here and it does like an interesting photo, with the fisheye and long exposure etc.<br/> <br/>Keep up the good work, just go easy on the HDR! :-)</td>', 'FWIW, this image strikes me more as digital art than a photograph.  There are lots of cool elements here and it does like an interesting photo, with the fisheye and long exposure etc. Keep up the good work, just go easy on the HDR! :-)', '2011-08-29 09:52:59.000000', NULL, 0),
(6519413, 967901, 67697, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by genova24:</b></div><hr/><i> Next time I know DPC is a more true to the art contest.  Thanks for all of the comments and votes. </i></td></tr></table> <br/> <br/>DPC is hardly a true to the art contest.  It''s all about clear, simple, easy to view photos that have sharp detail and great color.<br/> <br/>:)<br/> <br/>Shoot what you love and don''t let this place dictate how you do it.</td>', 'Originally posted by genova24: Next time I know DPC is a more true to the art contest.  Thanks for all of the comments and votes.   DPC is hardly a true to the art contest.  It''s all about clear, simple, easy to view photos that have sharp detail and great color. :) Shoot what you love and don''t let this place dictate how you do it.', '2011-08-29 09:57:40.000000', NULL, 0),
(6519415, 968224, 67697, '<td valign="top">I really liked this one.  I loved the clarity of the shallow end of the water and just seeing people enjoy the location.  Great slice of life shot.</td>', 'I really liked this one.  I loved the clarity of the shallow end of the water and just seeing people enjoy the location.  Great slice of life shot.', '2011-08-29 09:59:41.000000', NULL, 0),
(6519420, 968625, 12611, '<td valign="top">Nice shot- congrats- I like the stones with the green on them, as well as the wet wood. super details.</td>', 'Nice shot- congrats- I like the stones with the green on them, as well as the wet wood. super details.', '2011-08-29 10:13:00.000000', NULL, 0),
(6519425, 967901, 117474, '<td valign="top">One of the ways I judge images and vote is as follows: do I think the processing effect lends itself well to the image? <br/> <br/>In this case the answer is no. I would have loved to have seen this with subtler processing with perhaps the liberal saturation boost that is here if that''s what you''re looking for. I think a strong sharp contrasted image would have scored much better. <br/> <br/>However, this is just my opinion. I don''t know what you were trying to achieve. If it was this you did it excellently. I really do like the perspective used here.</td>', 'One of the ways I judge images and vote is as follows: do I think the processing effect lends itself well to the image?  In this case the answer is no. I would have loved to have seen this with subtler processing with perhaps the liberal saturation boost that is here if that''s what you''re looking for. I think a strong sharp contrasted image would have scored much better.  However, this is just my opinion. I don''t know what you were trying to achieve. If it was this you did it excellently. I really do like the perspective used here.', '2011-08-29 10:23:31.000000', NULL, 0),
(6519426, 968497, 30982, '<td valign="top">Nice!  I go camping with my brother and his boys from time to time and this captures the essence of the feeling very well!</td>', 'Nice!  I go camping with my brother and his boys from time to time and this captures the essence of the feeling very well!', '2011-08-29 10:23:40.000000', NULL, 0),
(6519431, 968224, 30982, '<td valign="top">How did you get such awesome curvature with the 24-105?  Is it due to the full frame of the 5D?  You''ve got the title full of "c"s to which you can add "crystal clear" and "curvature".  Great shot for this challenge.</td>', 'How did you get such awesome curvature with the 24-105?  Is it due to the full frame of the 5D?  You''ve got the title full of "c"s to which you can add "crystal clear" and "curvature".  Great shot for this challenge.', '2011-08-29 10:26:04.000000', NULL, 0),
(6519434, 968445, 30982, '<td valign="top">This is a great street shot - don''t sell yourself short on it!  Excellent moment, and really lovely light.</td>', 'This is a great street shot - don''t sell yourself short on it!  Excellent moment, and really lovely light.', '2011-08-29 10:27:34.000000', NULL, 0),
(6519441, 968492, 30861, '<td valign="top">Wow, two ribbons in one week! I knew this was a winner as soon as I saw it; just makes you want to reach out and touch it!</td>', 'Wow, two ribbons in one week! I knew this was a winner as soon as I saw it; just makes you want to reach out and touch it!', '2011-08-29 10:30:13.000000', NULL, 0),
(6519468, 968525, 12611, '<td valign="top">good movement in this shot, great blues and greens, and I like the added contrast on such a bright shot. pity no challenge comments, now you got one!</td>', 'good movement in this shot, great blues and greens, and I like the added contrast on such a bright shot. pity no challenge comments, now you got one!', '2011-08-29 11:24:17.000000', NULL, 0),
